    iron_ladlepreheater = { name = "Železni predgrevalec zajemalk", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni predgrevalec zajemalk za livarje." },
    bronze_ladlepreheater = { name = "Bronast predgrevalec zajemalk", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast predgrevalec zajemalk za livarje." },
    silver_ladlepreheater = { name = "Srebrn predgrevalec zajemalk", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn predgrevalec zajemalk za livarje." },
    gilded_ladlepreheater = { name = "Pozlačen predgrevalec zajemalk", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen predgrevalec zajemalk za livarje." },
    jewel_set_ladlepreheater = { name = "Draguljast predgrevalec zajemalk", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast predgrevalec zajemalk za livarje." },
    royal_sovereign_ladlepreheater = { name = "Kraljevski suveren predgrevalec zajemalk", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren predgrevalec zajemalk z biseri za krono." },
}
local BUILDINGS = {
    ladlepreheater_workshop = { name = "Ladlepreheater delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    ladlepreheater_house = { name = "Ladlepreheater hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
